import { IAutoMovieFilmTimeline } from "@automovie/interface";
import { AutoMovieProductionProject } from "./AutoMovieProductionProject";
import { parseAutoMovieFilmTimeline } from "./parseAutoMovieFilmTimeline";

/**
 * Acquire a current project manifest and admit its generated timeline at the supplied compile fingerprint.
 *
 * @evidence contracts/common.md#principled-implementation Acquires the manifest once, then the same project supplies generated bytes to the canonical parser; descriptor/path admission and digest/schema checks stay with their actual owners.
 * @evidence contracts/common.md#clear-and-simple-design This thin project adapter connects open production, oracle and delivery readers to one timeline admission policy.
 * @evidence contracts/common.md#prohibited-implementation-shortcuts Manifest acquisition and later byte read are sequential, not one atomic source snapshot; neither absent records nor failed byte reads receive a substitute timeline.
 * @evidence contracts/common.md#meaningful-documentation Documents caller-established compile fingerprint, project-owned acquisition and propagated parser/native refusals.
 * @evidence contracts/performance.md#efficient-algorithms Includes current namespace/revision and manifest read/validation, generated B-byte guarded read and full timeline digest/parse/schema costs; no work disappears through delegation.
 * @evidence contracts/performance.md#reuse-equivalent-work One observed manifest is used for this parser call; later invocations reacquire it and no project result is memoized.
 * @evidence contracts/performance.md#bound-retention-and-release-resources Delegated owned-file acquisition attempts descriptor release; complete admitted timeline transfers without retained buffers, watchers or tasks in this adapter.
 */
export function readAutoMovieFilmTimeline(project: AutoMovieProductionProject, fingerprint: string): IAutoMovieFilmTimeline {
    return parseAutoMovieFilmTimeline({
        manifest: project.generatedManifest(),
        fingerprint,
        read: (file: string): Uint8Array => project.readGeneratedFile(file),
    });
}
